"""Points generated by each participant's captain per gameweek."""

import csv
from pathlib import Path

from .paths import DATABASE_DIR
from .config import load_config, get_entry_id_to_name

FIELDNAMES = [
    "gameweek",
    "participant",
    "captain",
    "captainBasePoints",
    "multiplier",
    "captainPoints",
]


def _find_captain(rows: list[dict]) -> dict | None:
    """Return the pick that actually carried the armband in a gameweek.

    Normally that is the player flagged isCaptain. When the captain did not play,
    FPL passes the armband to the vice-captain: the flagged captain then has a
    multiplier of 0 and another player has the doubled points instead.
    """
    flagged = next((r for r in rows if r["isCaptain"].lower() == "true"), None)
    if flagged is None:
        return None
    if int(flagged["multiplier"]) > 1:
        return flagged

    # Armband passed on: the (non-flagged) player with the highest multiplier
    others = [r for r in rows if r is not flagged and int(r["multiplier"]) > 1]
    if others:
        return max(others, key=lambda r: int(r["multiplier"]))
    return flagged


def _gameweeks_available(participant_dir: Path) -> list[int]:
    return sorted(int(p.stem) for p in participant_dir.glob("*.csv") if p.stem.isdigit())


def build_captain_points(
    entry_ids: list[int] | None = None,
    gameweeks: list[int] | None = None,
    participants_dir: str | Path = DATABASE_DIR / "participants",
    config_path: str = "config/participants.toml",
) -> tuple[list[dict], list[str]]:
    """Build one row per participant and gameweek with the captain's points.

    Args:
        entry_ids: Participants to include (all participants in the config if None)
        gameweeks: Gameweeks to include (every gameweek with picks if None)
        participants_dir: Directory containing participant picks
        config_path: Path to config file

    Returns:
        Tuple of (rows sorted by gameweek, captainPoints descending, participant;
        notes about participants/gameweeks that were skipped)
    """
    id_to_name = get_entry_id_to_name(load_config(config_path))
    if entry_ids is None:
        entry_ids = list(id_to_name)

    rows: list[dict] = []
    skipped: list[str] = []
    for entry_id in entry_ids:
        name = id_to_name.get(entry_id)
        if not name:
            raise ValueError(f"Participant ID {entry_id} not found in config")

        participant_dir = Path(participants_dir) / name
        if not participant_dir.is_dir():
            skipped.append(f"{name}: no picks directory")
            continue

        available = _gameweeks_available(participant_dir)
        for gameweek in gameweeks if gameweeks is not None else available:
            if gameweek not in available:
                skipped.append(f"{name}: no picks for gameweek {gameweek}")
                continue

            with open(participant_dir / f"{gameweek}.csv", "r", encoding="utf-8") as f:
                captain = _find_captain(list(csv.DictReader(f)))
            if captain is None:
                skipped.append(f"{name}: no captain in gameweek {gameweek}")
                continue

            base_points = int(captain["totalPoints"])
            multiplier = int(captain["multiplier"])
            rows.append({
                "gameweek": gameweek,
                "participant": name,
                "captain": captain["playerName"],
                "captainBasePoints": base_points,
                "multiplier": multiplier,
                "captainPoints": base_points * multiplier,
            })

    rows.sort(key=lambda r: (r["gameweek"], -r["captainPoints"], r["participant"]))
    return rows, skipped


def export_captain_points(
    entry_ids: list[int] | None = None,
    gameweeks: list[int] | None = None,
    output_file: str | None = None,
    participants_dir: str | Path = DATABASE_DIR / "participants",
    config_path: str = "config/participants.toml",
) -> tuple[Path, int, list[str]]:
    """Export captain points to CSV.

    The default output is <database>/captains/captain_points.csv, or
    captain_points_gw<N>[_<M>...].csv when specific gameweeks are selected so a
    partial run never overwrites the full file.

    Returns:
        Tuple of (output path, number of rows written, skipped notes)
    """
    rows, skipped = build_captain_points(entry_ids, gameweeks, participants_dir, config_path)
    if not rows:
        raise FileNotFoundError("No captain data found for the selected participants/gameweeks")

    if output_file is None:
        suffix = "_gw" + "_".join(str(gw) for gw in sorted(set(gameweeks))) if gameweeks else ""
        output_file = DATABASE_DIR / "captains" / f"captain_points{suffix}.csv"

    output_path = Path(output_file)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDNAMES)
        writer.writeheader()
        writer.writerows(rows)

    return output_path, len(rows), skipped
